def double_blind_verify(draft_citation, source_db):
    # Step 1: Exact String Match (Fast Path)
    clean_draft = normalize_text(draft_citation.text)
    exact_hit = source_db.query("SELECT * FROM kb WHERE content_text LIKE ?", clean_draft)
    if exact_hit:
        return {"status": "VERIFIED", "method": "EXACT", "score": 1.0}

    # Step 2: Vector Embedding Match (Deep Path)
    draft_vector = embedding_model.encode(draft_citation.text)
    # Nearest Neighbor Search
    neighbor = source_db.vector_search(draft_vector, limit=1)
    similarity = cosine_similarity(draft_vector, neighbor.vector)

    if similarity >= 0.95:
        return {"status": "VERIFIED", "method": "FUZZY_EMBEDDING", "score": similarity}

    # Step 3: Failure -> Create Ticket
    ticket = create_verification_ticket(draft_citation, neighbor, similarity)
    return {"status": "FAILED", "ticket_id": ticket.id, "score": similarity}

