func Approve(ctx, ticketID, totp) {
  user := ctx.User
  if !ValidateTOTP(user.Secret, totp) { return 403_INVALID_2FA }

  draft := db.GetDraft(ticketID)
  // Generate Immutable Signature
  payload := draft.Hash + user.ID + Now()
  signature := SHA256(payload)

  db.Update(ticketID, {
    'status': 'APPROVED',
    'approver_id': user.ID,
    'approval_signature': signature,
    'approved_at': Now()
  })

  AuditLog.Log('LEGAL_SIGN_OFF', user.ID, ticketID, signature)
}

