func TestCalculateL1Status_EdgeCases(t *testing.T) {
    // Case: Exactly 50.0% -> Should be Non-Class-I (Strict > 50% or >=50% depending on exact policy, usually >=50)
    // Let's assume policy is >= 50%
    items := []Item{{Cost: 100, LocalPct: 50}}
    res := CalculateL1(items)
    if res.Status != "CLASS_I" { t.Errorf("Expected CLASS_I for 50%%, got %s", res.Status) }

    // Case: Zero Value Contract
    itemsZero := []Item{}
    resZero := CalculateL1(itemsZero)
    if resZero.Status != "ERROR" { t.Error("Expected ERROR for zero items") }
}

